using TCAdmin.SDK.Misc.OperatingSystem;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Don't do anything if mod type is not curse
if(!Globals.Variables.TryGetValue<string>("ModType", out var modType) || modType!="curse") return;

// Main execution
CurseForgeModpacks installer = null;
var deleteWorld = Globals.GetValue<bool>("DeleteWorld");
var totalSteps = deleteWorld ? 6 : 5;
installer = new CurseForgeModpacks(Globals, totalSteps);

var modpackInfo = await installer.GetModpackInformation();
var fileName = installer.DownloadModpack(modpackInfo).Result;
var (installerJar, specificVersion) = await installer.ExtractModpack(fileName);

if(installerJar!=null && installerJar.IndexOf("packwiz") != -1) installerJar = null;

var (modloaderInfo, isNeo) = await installer.InstallModloader(modpackInfo, installerJar, specificVersion);
await installer.SetCommandLine(modloaderInfo, isNeo);
if (deleteWorld)
{
    var propertiesFile = Path.Combine(Globals.ThisService.RootDirectory, "server.properties");
    var levelName = installer.GetLevelName(propertiesFile);
    installer.DeleteWorldFolders(levelName);
}

