installer=null;

// CurseForge class
class CurseForgeModpacks : IDisposable
{
    private readonly string _modpackId;
    private readonly string _modpackVersion;
    private readonly string _modLoaderType;
    private readonly string _gameVersion;
    private readonly bool _deleteWorldFolders;
    private readonly string _apiKey;
    private readonly int _totalSteps;
    private readonly HttpClient _httpClient;
    private readonly string _tcAdminFolder;
    private readonly MinecraftModpacksProvider _provider;
    private readonly CSharpGameGlobals Globals;

    public CurseForgeModpacks(CSharpGameGlobals globals, int totalSteps)
    {
        Globals = globals;
        _tcAdminFolder = Globals.TCAdminConfig.TCAdminPath;
        _modpackId = Globals.GetValue<string>("ModId");
        _modpackVersion = Globals.GetValue<string>("ModVersion");
        _modLoaderType = Globals.GetValue<string>("LoaderType");
        _gameVersion = Globals.GetValue<string>("MinecraftVersion");
        _deleteWorldFolders = Globals.GetValue<bool>("DeleteWorld");
        _provider = Globals.GetValue<MinecraftModpacksProvider>("ModProvider");
        _apiKey = CurseBrowser.CURSE_API_KEY;
        _totalSteps = _deleteWorldFolders ? totalSteps - 2 : totalSteps - 1;
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Add("x-api-key", _apiKey);
    }

    public void WriteLog(string s, int? progress = null, bool rewriteLastLog = false)
    {
        if(Globals.ThisTaskStepHandler != null)
        {
            Globals.ThisTaskStepHandler.UpdateProgress(progress: progress, log: s);
        }
        else if(Globals.ThisTaskStep!=null)
        {
            if(progress.HasValue)
            {
                Globals.ThisTaskStep.Progress = progress.Value;
            }

            if(rewriteLastLog)
            {
                Globals.ThisTaskStep.DisplayLog = s;
                Globals.ThisTaskStep.DisplayDebugLog = s;
            }
            else
            {
                Globals.ThisTaskStep.AddDebugLog(s, skipDuplicates:true);
            }
            Globals.TCATaskManager.Update(Globals.ThisTask, true);
        }
        else
        {
            Globals.ScriptConsole.WriteLine(s);
        }
    }

    public void SetDisplayMessage(string s)
    {
        if(Globals.ThisTaskStep!=null)
        {
            Globals.ThisTaskStep.DisplayLog = s;
            Globals.ThisTaskStep.DisplayDebugLog = s;
            Globals.TCATaskManager.Update(Globals.ThisTask, true);
        }
        else
        {
            Globals.ScriptConsole.WriteLine(s);
        }
    }

    public void UpdateProgress(int progress)
    {
        if(Globals.ThisTaskStepHandler != null)
        {
            WriteLog(null, progress);
        }
    }

    public async Task<LatestFile> GetModpackInformation()
    {
        WriteLog($"1/{_totalSteps} - Getting information about the modpack ID {_modpackId} version {_modpackVersion}...");
        
        var modpackInfo = await CurseBrowser.GetFile(_modpackId, _modpackVersion);
        
        if (!modpackInfo.IsServerPack && modpackInfo.ServerPackFileId > 0)
        {
            var serverPackId = modpackInfo.ServerPackFileId.ToString();
            WriteLog($"1/{_totalSteps} - Serverpack ID: {serverPackId}");
            var serverpackInfo = await CurseBrowser.GetFile(_modpackId, serverPackId);
            
            if (serverpackInfo.GameVersions.Count == 0)
            {
                //modpackInfo = serverpackInfo.Clone();
                serverpackInfo.GameVersions = modpackInfo.GameVersions;
                serverpackInfo.SortableGameVersions = modpackInfo.SortableGameVersions;
                modpackInfo = serverpackInfo;
            }
            else
            {
                modpackInfo = serverpackInfo;
            }
            WriteLog($"1/{_totalSteps} - Serverpack information received");
        }
        
        UpdateProgress(33);
        return modpackInfo;
    }

    public async Task<string> DownloadModpack(LatestFile modpackInfo)
    {
        var fileName = modpackInfo.FileName;
        var fileSize = modpackInfo.FileLength / (1024 * 1024);
        var downloadUrl = modpackInfo.DownloadUrl;
        
        if (string.IsNullOrEmpty(downloadUrl))
        {
            var fileId = modpackInfo.Id;
            downloadUrl = $"https://edge.forgecdn.net/files/{fileId.Substring(0, 4)}/{fileId.Substring(fileId.Length - 3)}/{fileName}";
        }

        WriteLog($"2/{_totalSteps} - Downloading modpack \"{fileName}\" ({fileSize}MB)");
        var filePath = Path.Combine(Globals.ThisService.RootDirectory, fileName);
        
        
        using (var response = await _httpClient.GetAsync(downloadUrl, HttpCompletionOption.ResponseHeadersRead, Globals.ThisCancellationToken))
        using (var stream = await response.Content.ReadAsStreamAsync())
        using (var fileStream = new FileStream(filePath, FileMode.Create))
        {
            var totalBytes = response.Content.Headers.ContentLength ?? 0;
            var buffer = new byte[8192];
            var bytesRead = 0;
            var totalRead = 0L;
            var lastProgress = -1;
            
            while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                Globals.ThisCancellationToken.ThrowIfCancellationRequested();
                await fileStream.WriteAsync(buffer, 0, bytesRead);
                totalRead += bytesRead;
                var progress = (int)((double)totalRead / totalBytes * 100);
                if(progress != lastProgress)
                {
                    lastProgress = progress;
                    UpdateProgress(progress);
                }
            }
        }
        
        UpdateProgress(100);
        return fileName;
    }

    public async Task<(string installerJar, string specificModloaderVersion)> ExtractModpack(string fileName)
    {
        UpdateProgress(0);
        var specificModloaderVersion = (string)null;
        WriteLog($"3/{_totalSteps} - Extracting \"{fileName}\"");
        
        var zipFile = Path.Combine(Globals.ThisService.RootDirectory, fileName);
        var tmpDir = Path.Combine(Globals.ThisService.RootDirectory, $"{_modpackId}-tmp");
        if(!Directory.Exists(tmpDir)) Directory.CreateDirectory(tmpDir);

        var c = new CompressionTools(Globals.OperatingSystem)
        {
            ThrowException = true,
            KeepListOfExtractedFiles = true,
            SetFileOwnerAutomatically = true
        };
        var lastExtractProgress = -1;
        c.Extracting+=(o, e) => {
            var progress = (int)e.Progress;
            if(progress != lastExtractProgress)
            {
                lastExtractProgress = progress;
                UpdateProgress(progress);
            }
        };
        c.Decompress(zipFile, tmpDir, Globals.ThisCancellationToken);
        
        WriteLog($"3/{_totalSteps} - Extraction complete");
        var extractedFiles = c.ExtractedFiles;
        var regex = Globals.ThisServer.OperatingSystem == EOperatingSystem.Windows
            ? new Regex(@"^.*[\\/]+mods[\\/]+.*\.jar$")
            : new Regex(@"^.*/mods/.*\.jar$");

        var modsFound = extractedFiles.Any(f => regex.IsMatch(f));
        string installerJar = null;

        if (!modsFound && File.Exists(Path.Combine(tmpDir, "mods.csv")))
        {
            WriteLog($"3/{_totalSteps} - No mods folder, but mods.csv available. Downloading files...");
            var downloadFiles = File.ReadAllLines(Path.Combine(tmpDir, "mods.csv"))
                                .Select(line => line.Split(','))
                                .Where(parts => parts.Length >= 2)
                                .ToList();
            
            var totalFiles = downloadFiles.Count;
            var lastDownloadProgress = -1;
            for (var i = 0; i < totalFiles; i++)
            {
                Globals.ThisCancellationToken.ThrowIfCancellationRequested();
                var parts = downloadFiles[i];
                var fileUrl = parts[0];
                var modFileName = parts[1];
                var modFilePath = Path.Combine(Globals.ThisService.RootDirectory, modFileName);
                var modDir = Path.GetDirectoryName(modFilePath);
                
                if (!Directory.Exists(modDir))
                    Directory.CreateDirectory(modDir);
                
                var progress = (int)((double)i / totalFiles * 100);
                if(progress != lastDownloadProgress)
                {
                    lastDownloadProgress = progress;
                    WriteLog($"3/{_totalSteps} - Downloading file {i+1}/{totalFiles} ({progress}%)", progress, true);
                }
                
                using (var response = await _httpClient.GetAsync(fileUrl, HttpCompletionOption.ResponseHeadersRead, Globals.ThisCancellationToken))
                {
                    response.EnsureSuccessStatusCode();
                    using (var stream = await response.Content.ReadAsStreamAsync())
                    using (var fileStream = new FileStream(modFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
                    {
                        await stream.CopyToAsync(fileStream);
                    }
                }
                
                if (modFileName.Contains("-installer.jar"))
                    installerJar = Path.GetFileName(modFileName);
            }
        }
        else if (modsFound)
        {
            var modsFile = extractedFiles.First(f => regex.IsMatch(f));
            var modsDir = Path.GetDirectoryName(modsFile);
            var basePath = Globals.ThisServer.OperatingSystem == EOperatingSystem.Windows
                ? modsDir.Replace("\\mods", "")
                : modsDir.Replace("/mods", "");
            
            installerJar = extractedFiles
                .FirstOrDefault(f => f.EndsWith("-installer.jar", StringComparison.OrdinalIgnoreCase));
            installerJar = installerJar != null ? Path.GetFileName(installerJar) : null;

            var totalFiles = extractedFiles.Count;
            var lastMoveProgress = -1;
            for (var i = 0; i < totalFiles; i++)
            {
                Globals.ThisCancellationToken.ThrowIfCancellationRequested();
                var file = extractedFiles[i];
                if (Path.GetFileName(file) == "eula.txt") continue;
                
                var dest = Path.Combine(Globals.ThisService.RootDirectory, file.Replace(basePath, "").TrimStart(Path.DirectorySeparatorChar));
                var destDir = Path.GetDirectoryName(dest);
                
                if (Path.GetFileName(file) == "variables.txt")
                {
                    WriteLog($"3/{_totalSteps} - variables.txt found. Loading modloader version...");
                    specificModloaderVersion = File.ReadAllLines(file)
                        .Where(line => !line.Trim().StartsWith("#") && line.Contains('='))
                        .Select(line => line.Split('='))
                        .Where(parts => parts.Length > 1 && parts[0].Trim() == "MODLOADER_VERSION")
                        .Select(parts => parts[1].Trim())
                        .FirstOrDefault();
                    
                    WriteLog($"3/{_totalSteps} - Modloader version: {specificModloaderVersion}");
                    continue;
                }
                
                if (!Directory.Exists(destDir))
                    Directory.CreateDirectory(destDir);
                
                File.Move(file, dest, true);
                var progress = 50 + (int)((double)i / totalFiles * 50);
                if(progress != lastMoveProgress)
                {
                    lastMoveProgress = progress;
                    WriteLog($"3/{_totalSteps} - Moving files ({i+1}/{totalFiles})", progress, true);
                }
            }
            
            WriteLog($"3/{_totalSteps} - All files moved");
            while (true)
            {
                Globals.ThisCancellationToken.ThrowIfCancellationRequested();
                try
                {
                    File.Delete(zipFile);
                    var fabricProps = Path.Combine(Globals.ThisService.RootDirectory, "fabric-server-launcher.properties");
                    if (File.Exists(fabricProps)) File.Delete(fabricProps);
                    if (Directory.Exists(tmpDir)) Directory.Delete(tmpDir, true);
                    break;
                }
                catch
                {
                    WriteLog($"3/{_totalSteps} - File still in use, retrying...");
                    Thread.Sleep(1000);
                }
            }
        }
        else
        {
            throw new Exception($"3/{_totalSteps} - No mods available in the pack");
        }
        
        UpdateProgress(100);
        return (installerJar, specificModloaderVersion);
    }

    public async Task<(string[] modloaderInfo, bool isNeo)> InstallModloader(LatestFile modloader, string includedInstallerJar, string specificModloaderVersion)
    {
        WriteLog($"4/{_totalSteps} - Beginning modloader installation");
        UpdateProgress(0);
        
        var modloaderType = modloader.SortableGameVersions
            .FirstOrDefault(v => v.GameVersionTypeId == 68441)?.GameVersionName;

        var gameVersions = modloader.GameVersions.ToList();

        if (gameVersions.Count < 2 && string.IsNullOrEmpty(_modLoaderType))
            throw new Exception("You need to specify a modloader to install");

        gameVersions.Sort();
        var gameVersion = !string.IsNullOrEmpty(_gameVersion) ? _gameVersion : gameVersions[0];
        var isNeo = false;
        string modloaderVersion = null;
        string installerJar = null;
        string modloaderJar = null;

        if (string.IsNullOrEmpty(includedInstallerJar) || specificModloaderVersion != null)
        {
            if (_modLoaderType == "Forge" || _modLoaderType == "NeoForge" || 
                modloaderType == "Forge" || modloaderType == "NeoForge")
            {
                isNeo = _modLoaderType == "NeoForge" || modloaderType == "NeoForge";
                var loaderResponse = _httpClient.GetAsync($"https://api.curseforge.com/v1/minecraft/modloader?version={gameVersion}", Globals.ThisCancellationToken).Result;
                loaderResponse.EnsureSuccessStatusCode();
                var loaderData = JsonDocument.Parse(loaderResponse.Content.ReadAsStringAsync().Result);
                var latestVersions = loaderData.RootElement.GetProperty("data").EnumerateArray()
                    .Where(v => v.GetProperty("latest").GetBoolean())
                    .Select(v => v.GetProperty("name").GetString())
                    .ToList();
                
                modloaderVersion = latestVersions.Max();
                var versionResponse = _httpClient.GetAsync($"https://api.curseforge.com/v1/minecraft/modloader/{modloaderVersion}", Globals.ThisCancellationToken).Result;
                versionResponse.EnsureSuccessStatusCode();
                var versionData = JsonDocument.Parse(versionResponse.Content.ReadAsStringAsync().Result);
                var forgeVersion = versionData.RootElement.GetProperty("data").GetProperty("forgeVersion").GetString();
                modloaderVersion = specificModloaderVersion ?? forgeVersion;
                
                // Handle old Forge versions
                if ((_modLoaderType == "Forge" || modloaderType == "Forge") && 
                    new Version(modloaderVersion).CompareTo(new Version("12.18.0.2008")) < 0)
                {
                    modloaderVersion += "-" + gameVersion;
                }
                
                if (isNeo)
                {
                    var mcVersion = versionData.RootElement.GetProperty("data").GetProperty("minecraftVersion").GetString();
                    if(new Version(mcVersion).CompareTo(new Version("1.20.1")) > 0)
                    {
                        var neoforgePrefix = GetNeoForgeVersion(gameVersion);

                        // Step 1: Download the XML
                        var  MetadataUrl = "https://maven.neoforged.net/releases/net/neoforged/neoforge/maven-metadata.xml";
                        using var client = new HttpClient();
                        var xmlData = await client.GetStringAsync(MetadataUrl);
                        
                        // Step 2: Parse the XML
                        var doc = XDocument.Parse(xmlData);
                        var versions = doc
                        .Root
                        .Element("versioning")
                        .Element("versions")
                        .Elements("version")
                        .Select(x => x.Value);

                        // Step 3: Filter by prefix
                        var matching = versions
                            .Where(v => v.StartsWith(neoforgePrefix, StringComparison.OrdinalIgnoreCase))
                            .ToList();

                        if (matching.Count == 0)
                                    throw new InvalidOperationException(
                                        $"Could not find a Neoforge version starting with '{neoforgePrefix}'.");

                        // Step 4: Sort and pick latest
                        matching.Sort(CompareVersionKeys);
                        modloaderVersion = matching.SingleOrDefault(x=>x == modloaderVersion) ?? matching[^1];  // last element

                        installerJar = $"https://maven.neoforged.net/releases/net/neoforged/neoforge/{modloaderVersion}/neoforge-{modloaderVersion}-installer.jar";
                    }
                    else
                    {
                        WriteLog("NeoForge version is smaller than 1.20.1");

                        installerJar = $"https://maven.neoforged.net/releases/net/neoforged/forge/{gameVersion}-{modloaderVersion}/forge-{gameVersion}-{modloaderVersion}-installer.jar";

                    }
                }

                if(!isNeo)
                {
                    installerJar = $"https://maven.minecraftforge.net/net/minecraftforge/forge/{gameVersion}-{modloaderVersion}/forge-{gameVersion}-{modloaderVersion}-installer.jar";
                }
                
                modloaderJar = versionData.RootElement.GetProperty("data").GetProperty("filename").GetString();
            }
            else if (_modLoaderType == "Fabric" || modloaderType == "Fabric")
            {
                var fabricMetadata = _httpClient.GetStringAsync("https://maven.fabricmc.net/net/fabricmc/fabric-installer/maven-metadata.xml").Result;
                var doc = XDocument.Parse(fabricMetadata);
                modloaderVersion = doc.Descendants("release").First().Value;
                installerJar = $"https://maven.fabricmc.net/net/fabricmc/fabric-installer/{modloaderVersion}/fabric-installer-{modloaderVersion}.jar";
                modloaderJar = "fabric-server-launch.jar";
            }
            
            var installerPath = Path.Combine(Globals.ThisService.RootDirectory, Path.GetFileName(installerJar));

            using (var response = await _httpClient.GetAsync(installerJar, HttpCompletionOption.ResponseHeadersRead, Globals.ThisCancellationToken))
            {
                response.EnsureSuccessStatusCode();
                var totalBytes = response.Content.Headers.ContentLength ?? -1L;
                var canReportProgress = totalBytes != -1;

                using (var contentStream = await response.Content.ReadAsStreamAsync())
                using (var fileStream = new FileStream(installerPath, FileMode.Create, FileAccess.Write, FileShare.None, 8192, true))
                {
                    var buffer = new byte[8192];
                    long totalRead = 0;
                    int read;
                    var lastProgress = -1;
                    WriteLog($"4/{_totalSteps} - Downloading modloader \"{installerJar}\"");

                    while ((read = await contentStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                    {
                        Globals.ThisCancellationToken.ThrowIfCancellationRequested();
                        await fileStream.WriteAsync(buffer, 0, read);
                        totalRead += read;

                        if (canReportProgress)
                        {
                            var progress = (int)((totalRead * 100L) / totalBytes);
                            if(progress != lastProgress)
                            {
                                lastProgress = progress;
                                UpdateProgress(progress);
                            }
                        }
                    }
                }
            }
            
            installerJar = Path.GetFileName(installerJar);
        }
        else
        {
            isNeo = _modLoaderType == "NeoForge" || modloaderType == "NeoForge";
            installerJar = includedInstallerJar;
            WriteLog($"4/{_totalSteps} - Modloader installer found in modpack ({installerJar})");
            modloaderJar = installerJar.Replace("-installer", "");
            
            if (modloaderJar.Contains("fabric"))
            {
                modloaderVersion = modloaderJar.Replace("fabric-", "").Replace(".jar", "").Replace("-", "");
                modloaderJar = "fabric-server-launch.jar";
            }
            else
            {
                modloaderVersion = modloaderJar
                    .Replace($"forge-{gameVersion}-", "")
                    .Replace("neoforge-", "")
                    .Replace(".jar", "");
            }
        }

        WriteLog($"4/{_totalSteps} - Installing modloader", -1);
        var args = (_modLoaderType.EndsWith("Forge") || _modLoaderType.EndsWith("Forge") || isNeo)
            ? $"-jar {installerJar} --installServer"
            : $"-jar {installerJar} server -downloadMinecraft -mcversion {gameVersion} -dir {Globals.ThisService.RootDirectory}";
        
        Process p;
        if (Globals.ThisServer.OperatingSystem == EOperatingSystem.Windows)
        {
            var startInfo = new ServiceToolStartOptions
            {
                Executable = Path.Combine(Globals.ThisService.RootDirectory, Globals.ThisService.Executable),
                WorkingDirectory = Globals.ThisService.RootDirectory,
                Arguments = args
            };

            var startResult = await Globals.ServiceManagerService.StartService(Globals.ThisService.ServiceId, startInfo);

            if(!startResult.Success) throw new Exception("Could not start installer process");

            p = Process.GetProcessById(startResult.ProcessId);
        }
        else
        {
            var psi = new ProcessStartInfo
            {
                FileName = Path.Combine(Globals.ThisService.RootDirectory, Globals.ThisService.Executable),
                Arguments = args,
                WorkingDirectory = Globals.ThisService.RootDirectory,
                UseShellExecute = false
            };

            var runAs = Globals.ServiceManagerService.GetSafeAccessTokenAndCredential(Globals.ThisService.ServiceId).Credential;
            if(runAs != null && !string.IsNullOrEmpty(runAs.UserName))
            {
                psi.UserName = runAs.UserName;
                var owner = Globals.OperatingSystem.GetOwner(Globals.ThisService.RootDirectory);
                Globals.OperatingSystem.SetDirectoryOwner(Globals.ThisService.RootDirectory, string.Empty, owner, true);
            }

            LinuxSystemUtility.MakeExecutable(psi.FileName);
            p = Process.Start(psi);
            if (p == null) throw new Exception("Could not start installer process");
        }
        p.EnableRaisingEvents = true;
        UpdateProgress(-1);
        Globals.Globals.ThisCancellationToken.Register(() => {
            if(p != null && !p.HasExited) p.Kill(true);
        });
        await p.WaitForExitAsync(Globals.Globals.ThisCancellationToken);
        UpdateProgress(100);
        
        if (p.ExitCode != 0)
        {
            if ((_modLoaderType == "Fabric" || modloaderType == "Fabric") && !string.IsNullOrEmpty(includedInstallerJar))
                throw new Exception("Fabric modloader installation failed. Try another version/modloader");
            
            if ((_modLoaderType.EndsWith("Forge") || modloaderType.EndsWith("Forge")) && !string.IsNullOrEmpty(includedInstallerJar))
            {
                WriteLog($"4/{_totalSteps} - Included Forge failed. Trying latest for {gameVersion}");
                return await InstallModloader(modloader, null, null);
            }
            p=null;
            throw new Exception("Modloader installation failed. Check logs for details.");
        }
        else
        {
            p=null;
        }
        
        // Check for universal jar
        if ((_modLoaderType == "Forge" || modloaderType == "Forge") && !isNeo)
        {
            var universalJar = Path.Combine(Globals.ThisService.RootDirectory, installerJar.Replace("-installer", "-universal"));
            WriteLog($"4/{_totalSteps} - Checking if Forge installer created universal jar {universalJar}");
            if (File.Exists(universalJar))
            {
                modloaderJar = Path.GetFileName(universalJar);
                WriteLog($"4/{_totalSteps} - Using universal jar: {modloaderJar}");
            }
        }
        
        UpdateProgress(90);
        WriteLog($"4/{_totalSteps} - Modloader installed");
        
        // Cleanup
        var installerPathToDelete = Path.Combine(Globals.ThisService.RootDirectory, installerJar);
        if (File.Exists(installerPathToDelete)) File.Delete(installerPathToDelete);
        
        UpdateProgress(100);

        return (new[] { modloaderJar, gameVersion, modloaderVersion }, isNeo);
    }

    public async Task SetCommandLine(string[] modloaderInfo, bool isNeo)
    {
        WriteLog($"5/{_totalSteps} - Configuring commandline");
        var variables = new TCAdminVars() {
            {_provider.JarVariableName, modloaderInfo[0].Replace(Globals.ThisService.RootDirectory, "")}
        };

        // Delete previous command line
        var prevCmdLineKey=$"{_provider.InstallPrefix}:CustomModsCmd";
        if(Globals.ThisService.Variables.TryGetValue<long?>(prevCmdLineKey, out var prevCmdLineId))
        {
            WriteLog($"5/{_totalSteps} - Deleting previous commandline");
            var prevCmdLine = Globals.ThisService.CustomCommandLines.SingleOrDefault(x=>x.CmdLineId==prevCmdLineId);
            if(prevCmdLine!=null) Globals.ThisService.CustomCommandLines.Remove(prevCmdLine);
        }

        var cmdLine = new ServiceCustomCommandLine
        { 
            Name=Globals.ThisTaskStep.DisplayName,
            CommandLine = Globals.ThisGame.CommandlineConfig.DefaultCommandline,
            Variables = variables
        };
        Globals.ThisService.CustomCommandLines.Add(cmdLine);

        if (Version.TryParse($"{modloaderInfo[2].Split('.')[0]}.0", out var parsed) && parsed.CompareTo(new Version("37.0")) < 0 && !isNeo)
        {
            // Nothing to do?
        }
        else
        {
            var argsOs = Globals.ThisServer.OperatingSystem == EOperatingSystem.Windows ? "win" : "unix";
            var forgeType = isNeo ? "neoforged" : "minecraftforge";
            var jarVar = $"-jar ${{{_provider.JarVariableName}}}";
            
            // WriteLog($"5/{_totalSteps} - Detected isNeo: {isNeo} forgeType: {forgeType} jarVar: {jarVar} modloaderInfo: {modloaderInfo.ToJson()}");
            cmdLine.OverrideDefault = true;
            if (isNeo && new Version(modloaderInfo[1]).CompareTo(new Version("1.20.1")) > 0)
            {
                cmdLine.CommandLine = cmdLine.CommandLine.Replace(jarVar, $"@libraries/net/{forgeType}/neoforge/{modloaderInfo[2]}/{argsOs}_args.txt");
            }
            else
            {
                cmdLine.CommandLine=cmdLine.CommandLine.Replace(jarVar, $"@libraries/net/{forgeType}/forge/{modloaderInfo[1]}-{modloaderInfo[2]}/{argsOs}_args.txt");
            }
        }

        await Globals.ServiceManager.UpdateAsync(Globals.ThisService, true, default);
        Globals.ThisService.Variables[prevCmdLineKey] = cmdLine.CmdLineId;
        Globals.ThisService.Variables[$"{_provider.InstallPrefix}:Type"] = "Curse";
        Globals.ThisService.Variables["__SelectedCmdLine"] = $"CUS:{cmdLine.CmdLineId}";
        
        var appliedCmdline = await Globals.ServiceManager.ApplyCustomCommandLine(null, Globals.ThisService.ServiceId, cmdLine.CmdLineId, false);
        if(!appliedCmdline) throw new Exception($"Could not apply command line id {cmdLine.CmdLineId}");

        await Globals.ServiceManager.UpdateAsync(Globals.ThisService, true, default);
    }

    public string GetLevelName(string filePath)
    {
        foreach (var line in File.ReadLines(filePath))
        {
            if (line.StartsWith("level-name="))
            {
                var levelName = line.Split('=')[1].Trim();
                WriteLog($"6/{_totalSteps} - Level name detected: {levelName}");
                return levelName;
            }
        }
        return null;
    }

    public void DeleteWorldFolders(string levelName)
    {
        if (string.IsNullOrEmpty(levelName))
        {
            WriteLog($"6/{_totalSteps} - Level name empty. Skipping deletion");
            return;
        }
        
        WriteLog($"6/{_totalSteps} - Deleting world folders");
        var basePath = Path.Combine(Globals.ThisService.RootDirectory, levelName);
        var folders = new[]
        {
            basePath,
            basePath + "_the_end",
            basePath + "_nether"
        };
        
        foreach (var folder in folders)
        {
            if (Directory.Exists(folder))
            {
                Directory.Delete(folder, true);
                WriteLog($"6/{_totalSteps} - Deleted: {folder}");
            }
            else
            {
                WriteLog($"6/{_totalSteps} - Not found: {folder}");
            }
        }
    }

    public static (List<int> NumericParts, bool IsBeta) VersionKey(string v)
    {
        if (v == null) throw new ArgumentNullException(nameof(v));

        bool isBeta = v.Contains("-beta", StringComparison.OrdinalIgnoreCase);
        // Remove any "-beta" suffix (case-insensitive) before splitting
        string cleaned = v.Replace("-beta", "", StringComparison.OrdinalIgnoreCase);
        // Split on '.', parse each segment to int
        var numericParts = cleaned
            .Split('.', StringSplitOptions.RemoveEmptyEntries)
            .Select(p =>
            {
                if (!int.TryParse(p, out var n))
                    throw new FormatException($"Invalid numeric version component: '{p}' in version '{v}'");
                return n;
            })
            .ToList();

        return (numericParts, isBeta);
    }

    public static string GetNeoForgeVersion(string mcVersion)
    {
        if (string.IsNullOrWhiteSpace(mcVersion))
            throw new ArgumentException("Version must not be empty", nameof(mcVersion));

        var parts = mcVersion.Split('.', StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length < 2)
            throw new ArgumentException(
                "Invalid Minecraft version format. Use format like '1.21.1'", nameof(mcVersion));

        // Skip the first component and re-join the rest
        return string.Join('.', parts.Skip(1));
    }

    private static int CompareVersionKeys(string a, string b)
    {
        var (pa, betaA) = VersionKey(a);
        var (pb, betaB) = VersionKey(b);

        int len = Math.Max(pa.Count, pb.Count);
        for (int i = 0; i < len; i++)
        {
            int na = i < pa.Count ? pa[i] : 0;
            int nb = i < pb.Count ? pb[i] : 0;
            int cmp = na.CompareTo(nb);
            if (cmp != 0)
                return cmp;
        }

        // if numeric parts equal, non-beta (false) comes before beta (true)
        return betaA.CompareTo(betaB);
    }

