// Keeps this game's Updates and Mods lists in step with the mcjarfiles.com catalog.
// Bound to the SyncBlueprintContent event: the master server fires it once a day (and on
// "Run sync now" under Settings -> Data Retention & Maintenance). No service is in scope.
//
// Updates: drop-in server builds (Vanilla incl. its snapshots, Paper, Purpur, Leaf, Folia) -
//          one row per version, the FULL version history of each, grouped by build name.
//          The one exception is vanilla snapshots (SnapshotVersionsKept, newest first): the
//          catalog holds 700+ of them, they are throwaway dev builds, and rows are never
//          deleted - only the current crop is worth listing (they sort below the releases
//          inside the Vanilla group).
//          (A rolling "Vanilla Latest" get-latest-jar row was tried and removed: it
//          duplicates the newest versioned row and confused users.)
// Mods:    mod loaders (Fabric, Forge, NeoForge) and the Velocity proxy - one row PER VERSION,
//          the FULL stable history of each, grouped by loader and pinned to its version (the
//          loaders' versions track Minecraft versions, so the older rows are what lets players
//          run modded servers on older game versions). Each row is linked (by code marker,
//          never by script id) to the game's per-mod install/uninstall companion scripts,
//          which read the loader from the name's first token ("Forge 1.21.8" -> Forge) and wire
//          the service to actually launch the loader and revert on uninstall.
//          (The original single bare-named rows, bumped to latest, are renamed in place to their
//          versioned name on first sync - install tracking keeps pointing at the same row.)
//
// The web UI shows the newest handful of rows per group with a "View all" expander, so deep
// histories do not clutter the Updates/Mods pages.
//
// Never creates duplicates: rows are matched by Name and updated in place (source, version,
// release metadata, icon, sort order). Rows are never deleted - installed updates stay referenced,
// and anything an admin deletes by hand is re-imported on the next sync (unbind this script
// to stop imports instead).

// Vanilla snapshots kept (newest first). Every other variant imports its full history.
const int SnapshotVersionsKept = 10;
// The newest N versions of every variant get their release metadata re-fetched (and a missing
// file size re-probed) on EVERY run - recent builds like Paper are rebuilt in place, so their
// timestamp/channel can move. Older rows are fetched once when created and afterwards only
// healed while metadata is still missing, so a full-history catalog does not turn every daily
// run into hundreds of HTTP calls.
const int MetadataRefreshWindow = 10;
const string Api = "https://mcjarfiles.com/api";

var console = Globals.ScriptConsole;
var db = Globals.GameManager.TCAdminDbContext;
var gameId = Globals.ThisGame.BlueprintId;

// Role collections must be loaded, or the no-roles heal below would re-add duplicates.
var existingUpdates = db.GameUpdates.Include(u => u.UpdateRoles).Where(u => u.GameId == gameId).ToList();
var existingMods = db.BlueprintMods.Include(m => m.ModScripts).Include(m => m.ModRoles)
    .Where(m => m.BlueprintId == gameId).ToList();

var createdUpdates = 0;
var updatedUpdates = 0;
var createdMods = 0;
var updatedMods = 0;
var renamedMods = 0;
var linkedScripts = 0;
var filledSizes = 0;
var setIcons = 0;
var grantedRoles = 0;

// Updates and mods are deny-by-default: a row with NO roles is visible to admins only, so
// freshly imported rows would be invisible to sub-admins and users. Grant the default roles
// (first sub-admin role + first user role - the same resolution the V2 importer uses) to any
// row that has none. Only the no-roles state is healed, so role changes an admin makes later
// are left alone.
var defaultRoleIds = new List<long>();
var firstSubAdminRole = db.Roles.Where(r => r.RoleType == ERoleType.SubAdmin).OrderBy(r => r.RoleId).FirstOrDefault();
if (firstSubAdminRole != null) defaultRoleIds.Add(firstSubAdminRole.RoleId);
var firstUserRole = db.Roles.Where(r => r.RoleType == ERoleType.User).OrderBy(r => r.RoleId).FirstOrDefault();
if (firstUserRole != null) defaultRoleIds.Add(firstUserRole.RoleId);

void EnsureDefaultUpdateRoles(GameUpdate u)
{
    if (u.UpdateRoles.Count > 0 || defaultRoleIds.Count == 0) return;
    foreach (var roleId in defaultRoleIds)
    {
        u.UpdateRoles.Add(new GameUpdateRole { Update = u, RoleId = roleId });
        grantedRoles++;
    }
}

void EnsureDefaultModRoles(BlueprintMod m)
{
    if (m.ModRoles.Count > 0 || defaultRoleIds.Count == 0) return;
    foreach (var roleId in defaultRoleIds)
    {
        m.ModRoles.Add(new BlueprintModRole { Mod = m, RoleId = roleId });
        grantedRoles++;
    }
}

// Every imported mod gets the game's per-mod install/uninstall companion scripts (they run the
// Forge/NeoForge installer, swap the Jar variable, and revert it all on uninstall). Script ids
// differ between installs, so the scripts are found by the marker comment in their code - the
// same trick the modpack dispatcher script uses. The markers are concatenated here so this
// script's own code never matches the lookup.
var installMarker = "MCJARFILES-MOD-" + "INSTALL";
var uninstallMarker = "MCJARFILES-MOD-" + "UNINSTALL";
var modInstallScript = db.GameScripts.FirstOrDefault(s =>
    s.Code.Contains(installMarker) && (s.AllGames || s.GamesScripts.Any(g => g.GameId == gameId)));
var modUninstallScript = db.GameScripts.FirstOrDefault(s =>
    s.Code.Contains(uninstallMarker) && (s.AllGames || s.GamesScripts.Any(g => g.GameId == gameId)));
if (modInstallScript == null || modUninstallScript == null)
{
    console.WriteLine("Warning: the mod install/uninstall companion script(s) were not found by marker - mods will import without scripts.");
}

// Links are added on create AND healed on later runs (idempotent by ScriptId).
void EnsureModScript(BlueprintMod m, GameScript s)
{
    if (s == null) return;
    if (m.ModScripts.Any(ms => ms.ScriptId == s.ScriptId)) return;
    m.ModScripts.Add(new BlueprintModScript { Mod = m, Script = s, ScriptId = s.ScriptId });
    linkedScripts++;
}

// (releaseType, releaseDate, icon) from a get-version-info payload. channel "default" means a
// stable build; any other channel becomes the badge text. Vanilla payloads carry no "channel" -
// their channel lives in "build" ("release"/"snapshot"), so a STRING build is the fallback
// (Paper-style payloads reuse "build" for the numeric build NUMBER, which must not match).
// icon is the catalog's icon URL (added to the API 2026-08; null when the payload has none).
(string ReleaseType, DateTime? ReleaseDate, string Icon) ParseInfo(JsonElement info)
{
    // modded/* returns an ARRAY of builds (newest first; fields time/forgeVersion/downloadUrl,
    // no channel), while vanilla/servers return a single object. Normalize to the newest build.
    if (info.ValueKind == JsonValueKind.Array)
    {
        if (info.GetArrayLength() == 0)
        {
            return ("Release", null, null);
        }
        info = info[0];
    }

    var releaseType = "Release";
    if (info.TryGetProperty("channel", out var channel) && channel.ValueKind == JsonValueKind.String)
    {
        var c = channel.GetString();
        if (!string.IsNullOrEmpty(c) && !string.Equals(c, "default", StringComparison.OrdinalIgnoreCase))
        {
            releaseType = char.ToUpperInvariant(c[0]) + c.Substring(1);
        }
    }
    else if (info.TryGetProperty("build", out var build) && build.ValueKind == JsonValueKind.String)
    {
        var b = build.GetString();
        if (!string.IsNullOrEmpty(b) && !string.Equals(b, "release", StringComparison.OrdinalIgnoreCase))
        {
            releaseType = char.ToUpperInvariant(b[0]) + b.Substring(1);
        }
    }

    DateTime? releaseDate = null;
    if (info.TryGetProperty("time", out var time) && time.ValueKind == JsonValueKind.Number)
    {
        releaseDate = DateTimeOffset.FromUnixTimeMilliseconds((long)(time.GetDouble() * 1000)).UtcDateTime;
    }

    string icon = null;
    if (info.TryGetProperty("icon", out var iconProp) && iconProp.ValueKind == JsonValueKind.String
        && !string.IsNullOrWhiteSpace(iconProp.GetString()))
    {
        icon = iconProp.GetString();
    }

    return (releaseType, releaseDate, icon);
}

// True for plain dot-separated numeric versions ("1.21.8", "26.2", "4.1.1") - the shape every
// real loader/proxy release uses. Weeds out what the pre-release WORD filter cannot: Mojang
// snapshot ids ("24w09a"), combat-test builds ("1.16_combat-3"), "_unobfuscated" builds and
// April-Fools versions ("24w14potato", "3D Shareware v1.34"), which carry no marker word.
// (Deliberately a hand-rolled check: the runtime script host references fewer assemblies than
// CheckSyntax, so Regex is avoided.)
bool IsReleaseShaped(string v)
{
    var parts = v.Split('.');
    if (parts.Length < 2) return false;
    foreach (var part in parts)
    {
        if (part.Length == 0) return false;
        foreach (var ch in part)
        {
            if (ch < '0' || ch > '9') return false;
        }
    }
    return true;
}

using (var http = new HttpClient())
{
    http.Timeout = TimeSpan.FromSeconds(30);

    // ---- Game Updates: swappable server builds ------------------------------------------
    // Group is the Updates-page section; Prefix is the row-name prefix AND the match key for
    // existing rows, so it must stay stable. Snapshots share the Vanilla group (they're vanilla
    // builds too) but keep their "Snapshot" names - and because both variants share a group,
    // ViewOrder runs group-wide: the releases land first, the snapshots continue below them.
    // Cap 0 = full history; snapshots keep only the newest crop (see the header comment).
    var updateVariants = new[]
    {
        (Type: "vanilla", Variant: "release",  Group: "Vanilla", Prefix: "Vanilla",  Cap: 0),
        (Type: "vanilla", Variant: "snapshot", Group: "Vanilla", Prefix: "Snapshot", Cap: SnapshotVersionsKept),
        (Type: "servers", Variant: "paper",   Group: "Paper",  Prefix: "Paper",  Cap: 0),
        (Type: "servers", Variant: "purpur",  Group: "Purpur", Prefix: "Purpur", Cap: 0),
        (Type: "servers", Variant: "leafmc",  Group: "Leaf",   Prefix: "Leaf",   Cap: 0),
        (Type: "servers", Variant: "folia",   Group: "Folia",  Prefix: "Folia",  Cap: 0),
    };

    var groupOrders = new Dictionary<string, int>();
    foreach (var uv in updateVariants)
    {
        string[] versions;
        try
        {
            var json = await http.GetStringAsync($"{Api}/get-versions/{uv.Type}/{uv.Variant}");
            versions = JsonSerializer.Deserialize<string[]>(json) ?? Array.Empty<string>();
        }
        catch (Exception ex)
        {
            console.WriteLine($"[{uv.Group}] could not list versions: {ex.Message} - skipped");
            continue;
        }

        if (uv.Cap > 0)
        {
            versions = versions.Take(uv.Cap).ToArray();
        }

        var order = groupOrders.TryGetValue(uv.Group, out var startOrder) ? startOrder : 0;
        var idx = 0;
        foreach (var version in versions)
        {
            var name = $"{uv.Prefix} {version}";
            var source = $"{Api}/get-jar/{uv.Type}/{uv.Variant}/{version}";

            var row = existingUpdates.FirstOrDefault(u => u.Name == name);
            var isNew = row == null;

            // Metadata is re-fetched every run only inside the refresh window (builds like
            // Paper rebuild the same game version in place, so an existing row's timestamp
            // and channel can legitimately move). Deeper rows fetch on create and afterwards
            // only while date/icon are still missing (a heal that converges - the catalog
            // carries both fields down to its oldest versions).
            var releaseType = "Release";
            DateTime? releaseDate = null;
            string icon = null;
            var haveInfo = false;
            if (idx < MetadataRefreshWindow || isNew || row.ReleaseDate == null || row.Icon == null)
            {
                try
                {
                    var infoJson = await http.GetStringAsync($"{Api}/get-version-info/{uv.Type}/{uv.Variant}/{version}");
                    using (var doc = JsonDocument.Parse(infoJson))
                    {
                        var parsed = ParseInfo(doc.RootElement);
                        releaseType = parsed.ReleaseType;
                        releaseDate = parsed.ReleaseDate;
                        icon = parsed.Icon;
                        haveInfo = true;
                    }
                }
                catch (Exception ex)
                {
                    console.WriteLine($"[{name}] no release metadata: {ex.Message}");
                }
            }

            if (isNew)
            {
                row = new GameUpdate
                {
                    GameId = gameId,
                    Name = name,
                    GroupName = uv.Group,
                    Comments = $"{uv.Prefix} server build {version}. Imported from mcjarfiles.com.",
                    Source = source,
                    // Must match what the game's command line launches: -jar ${Jar}, whose
                    // default is minecraft_server.jar. A different filename would install
                    // fine but never be the jar the service actually runs.
                    SaveAsFilename = "minecraft_server.jar",
                    Reinstallable = true,
                    Version = version,
                    ReleaseType = releaseType,
                    ReleaseDate = releaseDate,
                    ViewOrder = order
                };
                db.GameUpdates.Add(row);
                existingUpdates.Add(row);
                createdUpdates++;
                console.WriteLine($"Added update: {name}");
            }
            else
            {
                var changed = row.Source != source || row.Version != version || row.ViewOrder != order
                              || row.SaveAsFilename != "minecraft_server.jar" || row.GroupName != uv.Group
                              || (haveInfo && (row.ReleaseType != releaseType || row.ReleaseDate != releaseDate));
                row.Source = source;
                row.Version = version;
                row.SaveAsFilename = "minecraft_server.jar";
                row.GroupName = uv.Group; // heals rows from before Snapshot merged into the Vanilla group
                row.ViewOrder = order;    // newest first within the group
                if (haveInfo)
                {
                    row.ReleaseType = releaseType;
                    row.ReleaseDate = releaseDate;
                }
                if (changed)
                {
                    updatedUpdates++;
                }
            }

            // Icon URL from the same metadata payload (rendered with priority over the game's
            // icon). Only written when the API actually sent one, so a fetch hiccup or a payload
            // without an icon never clears an existing icon.
            if (icon != null && row.Icon != icon)
            {
                row.Icon = icon;
                setIcons++;
            }

            EnsureDefaultUpdateRoles(row);

            // Display-only download size shown on the Updates page. mcjarfiles answers HEAD
            // on get-jar with the real Content-Length. Probed on create and, inside the
            // refresh window, whenever the size is still missing - deep-history rows are NOT
            // re-probed every run.
            if (row.FileSizeBytes == null && (idx < MetadataRefreshWindow || isNew))
            {
                try
                {
                    using (var sizeReq = new HttpRequestMessage(HttpMethod.Head, source))
                    using (var sizeResp = await http.SendAsync(sizeReq))
                    {
                        if (sizeResp.IsSuccessStatusCode && sizeResp.Content.Headers.ContentLength > 0)
                        {
                            row.FileSizeBytes = sizeResp.Content.Headers.ContentLength;
                            filledSizes++;
                        }
                    }
                }
                catch (Exception ex)
                {
                    console.WriteLine($"[{name}] file size probe failed: {ex.Message}");
                }
            }

            order++;
            idx++;
        }

        groupOrders[uv.Group] = order;
    }

    // ---- Mods: loaders + proxy, one row per version, each pinned ------------------------
    var modVariants = new[]
    {
        (Type: "modded", Variant: "fabric", ModName: "Fabric",
            Homepage: "https://fabricmc.net",
            About: "Lightweight, modern mod loader."),
        (Type: "modded", Variant: "forge", ModName: "Forge",
            Homepage: "https://files.minecraftforge.net",
            About: "The classic mod loader."),
        (Type: "modded", Variant: "neoforge", ModName: "NeoForge",
            Homepage: "https://neoforged.net",
            About: "Actively developed Forge fork."),
        (Type: "proxies", Variant: "velocity", ModName: "Velocity",
            Homepage: "https://papermc.io/software/velocity",
            About: "Modern Minecraft proxy for multi-server networks."),
    };

    foreach (var mv in modVariants)
    {
        string[] versions;
        try
        {
            var json = await http.GetStringAsync($"{Api}/get-versions/{mv.Type}/{mv.Variant}");
            var all = JsonSerializer.Deserialize<string[]>(json) ?? Array.Empty<string>();
            // Mod rows point users at installable releases: the modded lists interleave Mojang
            // snapshots, -SNAPSHOT builds, combat tests and April-Fools versions with the real
            // releases, and only the plain-numbered versions are releases - so the shape check
            // IS the stable filter. Full stable history is imported; the raw list (capped - it
            // can run 500+ deep) is only a fallback for the day a catalog offers no stable
            // versions at all.
            var stable = all.Where(IsReleaseShaped).ToArray();
            versions = stable.Length > 0 ? stable : all.Take(MetadataRefreshWindow).ToArray();
        }
        catch (Exception ex)
        {
            console.WriteLine($"[{mv.ModName}] could not list versions: {ex.Message} - skipped");
            continue;
        }

        if (versions.Length == 0)
        {
            console.WriteLine($"[{mv.ModName}] no versions returned - skipped");
            continue;
        }

        // One-time migration: the first design imported ONE bare-named row per loader ("Forge")
        // and bumped it to the latest version. Rename it in place to the versioned name for the
        // version it already carries - installed-mod tracking keeps pointing at the same row,
        // and the versioned import below then matches it by name instead of duplicating it.
        var bare = existingMods.FirstOrDefault(m => m.Name == mv.ModName);
        if (bare != null && !string.IsNullOrEmpty(bare.Version))
        {
            var versionedName = $"{mv.ModName} {bare.Version}";
            if (existingMods.Any(m => m.Name == versionedName))
            {
                console.WriteLine($"Warning: both '{mv.ModName}' and '{versionedName}' exist - not renaming; remove one of them by hand.");
            }
            else
            {
                bare.Name = versionedName;
                bare.GroupName = mv.ModName;
                // The old description said "Latest ... imported" - no longer true for a pinned row.
                bare.Comments = mv.Type == "modded"
                    ? $"{mv.About} For Minecraft {bare.Version}. Imported from mcjarfiles.com."
                    : $"{mv.About} Version {bare.Version}. Imported from mcjarfiles.com.";
                renamedMods++;
                console.WriteLine($"Renamed mod: {mv.ModName} -> {versionedName}");
            }
        }

        var order = 0;
        foreach (var version in versions)
        {
            var name = $"{mv.ModName} {version}";
            var source = $"{Api}/get-jar/{mv.Type}/{mv.Variant}/{version}";
            // The loaders are versioned by the Minecraft version they target; Velocity versions
            // the proxy itself.
            var about = mv.Type == "modded"
                ? $"{mv.About} For Minecraft {version}. Imported from mcjarfiles.com."
                : $"{mv.About} Version {version}. Imported from mcjarfiles.com.";

            var row = existingMods.FirstOrDefault(m => m.Name == name);
            var isNew = row == null;

            // Same policy as the updates: every-run re-fetch inside the refresh window (the
            // jar behind a version can be rebuilt - the modded/* payloads are build arrays,
            // so an existing row's timestamp can move), fetch-on-create plus the converging
            // missing-metadata heal for the deep history.
            var releaseType = "Release";
            DateTime? releaseDate = null;
            string icon = null;
            var haveInfo = false;
            if (order < MetadataRefreshWindow || isNew || row.ReleaseDate == null || row.Icon == null)
            {
                try
                {
                    var infoJson = await http.GetStringAsync($"{Api}/get-version-info/{mv.Type}/{mv.Variant}/{version}");
                    using (var doc = JsonDocument.Parse(infoJson))
                    {
                        var parsed = ParseInfo(doc.RootElement);
                        releaseType = parsed.ReleaseType;
                        releaseDate = parsed.ReleaseDate;
                        icon = parsed.Icon;
                        haveInfo = true;
                    }
                }
                catch (Exception ex)
                {
                    console.WriteLine($"[{name}] no release metadata: {ex.Message}");
                }
            }

            var sourceChanged = false;
            if (isNew)
            {
                row = new BlueprintMod
                {
                    BlueprintId = gameId,
                    Name = name,
                    GroupName = mv.ModName,
                    Comments = about,
                    HomepageUrl = mv.Homepage,
                    // A null Source makes the install treat the mod as scripts-only (no download)
                    // and the install script then runs whatever stale installer jar is lying in
                    // the service root - Source must be set on create, not just on update.
                    Source = source,
                    // Versioned staged jar (e.g. fabric-26.2.jar): multiple versions of the same
                    // loader can be installed side by side, each with its own custom command line
                    // and its own JavaFor:<jar> memo. The companion scripts key off this filename.
                    SaveAsFilename = $"{mv.Variant}-{version}.jar",
                    InstallType = EModInstallType.Silent,
                    UpdateVisible = true,
                    Uninstallable = true,
                    TrackInstalledFiles = true,
                    Version = version,
                    ReleaseType = releaseType,
                    ReleaseDate = releaseDate,
                    ViewOrder = order
                };
                db.BlueprintMods.Add(row);
                existingMods.Add(row);
                createdMods++;
                console.WriteLine($"Added mod: {name}");
            }
            else
            {
                var saveAs = $"{mv.Variant}-{version}.jar";
                var changed = row.Source != source || row.Version != version || row.ViewOrder != order
                              || row.GroupName != mv.ModName || row.SaveAsFilename != saveAs
                              || (haveInfo && (row.ReleaseType != releaseType || row.ReleaseDate != releaseDate));
                if (row.Source != source)
                {
                    row.Source = source;
                    row.FileSizeBytes = null; // a different jar sits behind Source - re-probed below
                    sourceChanged = true;
                }
                // Heals pre-2026-08-28 rows off the shared bare name ({variant}.jar) - the install/
                // uninstall scripts handle the leftover bare files on already-installed services.
                row.SaveAsFilename = saveAs;
                row.Version = version;
                row.GroupName = mv.ModName; // migrates pre-versioning rows out of "Mod Loaders"/"Proxies"
                row.ViewOrder = order;      // newest first within the loader's group
                if (haveInfo)
                {
                    row.ReleaseType = releaseType;
                    row.ReleaseDate = releaseDate;
                }
                if (changed)
                {
                    updatedMods++;
                }
            }

            // Only written when the API actually sent one - a fetch hiccup never clears an icon.
            if (icon != null && row.Icon != icon)
            {
                row.Icon = icon;
                setIcons++;
            }

            EnsureModScript(row, modInstallScript);
            EnsureModScript(row, modUninstallScript);
            EnsureDefaultModRoles(row);

            // Same HEAD probe as the updates - on create, when Source changed, and inside the
            // refresh window while the size is still missing. Fabric stays null forever: its
            // get-jar generates the launcher on the fly and answers HEAD without a
            // Content-Length. That's expected, not a bug (and exactly why deep-history rows
            // must not be re-probed every run).
            if (row.FileSizeBytes == null && !string.IsNullOrEmpty(row.Source)
                && (order < MetadataRefreshWindow || isNew || sourceChanged))
            {
                try
                {
                    using (var sizeReq = new HttpRequestMessage(HttpMethod.Head, row.Source))
                    using (var sizeResp = await http.SendAsync(sizeReq))
                    {
                        if (sizeResp.IsSuccessStatusCode && sizeResp.Content.Headers.ContentLength > 0)
                        {
                            row.FileSizeBytes = sizeResp.Content.Headers.ContentLength;
                            filledSizes++;
                        }
                    }
                }
                catch (Exception ex)
                {
                    console.WriteLine($"[{name}] file size probe failed: {ex.Message}");
                }
            }

            order++;
        }
    }
}

await db.SaveChangesAsync();
console.WriteLine($"Sync complete: {createdUpdates} update(s) added, {updatedUpdates} updated, {createdMods} mod(s) added, {updatedMods} updated, {renamedMods} renamed, {linkedScripts} script link(s) added, {filledSizes} file size(s) filled, {setIcons} icon(s) set, {grantedRoles} role grant(s).");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Web.Shared.dll, TCAdmin.Monitor.SDK.dll
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.Database.Entities;
using TCAdmin.SDK.Database.Managers;
using TCAdmin.Web.Shared.Models;
var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// MCJARFILES-MOD-INSTALL  <- marker referenced by the "Sync Minecraft Updates & Mods
// (mcjarfiles.com)" script, which finds this script by searching the game's scripts for this
// text and attaches it to every imported mod. Script ids differ between installs, so mods
// reference this script by marker, never by id. Keep the marker intact.
//
// Runs on AfterModInstall for the mcjarfiles loader/proxy mods. The staged jar is already in
// the service root (VERSIONED since 2026-08-28, e.g. fabric-26.2.jar - the sync stamps
// SaveAs "{variant}-{version}.jar" so versions never overwrite each other); this script wires
// the service so it actually LAUNCHES the loader - by creating (or updating) ONE CUSTOM
// COMMAND LINE PER INSTALLED VERSION and making it the active selection. The default command
// line is never touched anymore, so with several loaders (or several versions of one loader)
// installed the user can switch between them (and back to vanilla) from the Command Lines page:
//   - Fabric / Velocity (runnable jars): a non-override line whose variable bag pins
//     Jar=<staged jar> - the blueprint's "-jar ${Jar}" template still supplies the JVM tuning.
//   - Forge / NeoForge (installer jars): run "java -jar <installer> --installServer", then an
//     override line that launches through the generated
//     @libraries/net/<vendor>/.../{win|unix}_args.txt argument file (modern Forge/NeoForge has
//     no runnable server jar). Memory still comes from ${Xmx}/${Xms} so the sliders keep working.
// Fabric additionally records the real Java requirement in a "JavaFor:<jar>" service variable -
// the game's "Detect java version" startup script prefers that memo over class-file sniffing
// (the Fabric launcher is a Java-8 bootstrap the sniff misreads as Java 8), so Automatic Java
// detection follows whichever command line is active instead of a global JavaVersion pin.
// The "Mod:<loader>:CmdLineId" service variable tracks each loader's line so reinstalls and
// version bumps update the same row. The companion uninstall script reverses all of this.

var console = Globals.ScriptConsole;
var mod = Globals.GetValue<BlueprintMod>(nameof(BlueprintMod));
var service = Globals.ThisService;
if (mod == null || service == null)
{
    console.WriteLine("No mod or service in scope - nothing to do.");
    return;
}

var db = Globals.ServiceManager.TCAdminDbContext;
var root = service.RootDirectory;
var jar = mod.SaveAsFilename;
var isWindows = System.OperatingSystem.IsWindows(); // qualified: bare OperatingSystem binds to the globals member

// The sync imports one row per version ("Forge 1.21.8"), so the loader is the name's first
// token - bare legacy names ("Forge") dispatch the same way.
var loader = mod.Name.Split(' ')[0];

if (string.IsNullOrEmpty(jar))
{
    console.WriteLine($"[{mod.Name}] has no Save As filename - nothing to wire up.");
    return;
}

var defaultTemplate = service.Blueprint?.CommandlineConfig?.DefaultCommandline;

// Per-branch outputs, converged into the custom-command-line upsert at the bottom.
string lineTemplate;
bool lineOverridesDefault;
var lineVars = new TCAdminVars();

if (loader == "Forge" || loader == "NeoForge")
{
    var installerPath = Path.Combine(root, jar);
    if (!File.Exists(installerPath))
    {
        throw new Exception($"Installer {jar} was not found in the service root.");
    }

    // Prefer the JRE the auto-setup bundled with the service; fall back to java on PATH.
    var javaExe = isWindows ? "java.exe" : "java";
    var java = javaExe;
    var javaDir = Path.Combine(root, "java");
    if (Directory.Exists(javaDir))
    {
        var bundled = Directory.GetFiles(javaDir, javaExe, SearchOption.AllDirectories).FirstOrDefault();
        if (bundled != null) java = bundled;
    }

    // The task dialog's VISIBLE log only shows what goes through ThisTaskStepHandler.UpdateProgress
    // (ScriptConsole output lands in the admin-only debug log), so without the pushes below the
    // dialog sits on "Executing after-install scripts" for the whole installer run. Null when this
    // script runs outside a task (script-called install) - console-only then.
    var taskHandler = Globals.ThisTaskStepHandler;
    var startMsg = $"Running the {mod.Name} installer (downloads libraries - this can take a few minutes)...";
    console.WriteLine(startMsg);
    if (taskHandler != null)
    {
        await taskHandler.UpdateProgress(log: startMsg);
    }

    var psi = new ProcessStartInfo
    {
        FileName = java,
        WorkingDirectory = root,
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true
    };
    psi.ArgumentList.Add("-jar");
    psi.ArgumentList.Add(installerPath);
    psi.ArgumentList.Add("--installServer");

    // Task path buffers the output instead of console-writing each line: every debug write is
    // mirrored into the step's user-visible log (AddDebugLog's addToLog default), so per-line
    // writes flood it with thousands of entries AND break the collapse of the rolling progress
    // entry below. Nothing is written to the DB mid-step, so buffering loses nothing on a crash.
    var pendingOutput = new ConcurrentQueue<string>();
    var fullOutput = new List<string>();
    using (var proc = Process.Start(psi))
    {
        proc.OutputDataReceived += (_, e) => { if (!string.IsNullOrWhiteSpace(e.Data)) { if (taskHandler != null) pendingOutput.Enqueue(e.Data); else console.WriteLine(e.Data); } };
        proc.ErrorDataReceived += (_, e) => { if (!string.IsNullOrWhiteSpace(e.Data)) { if (taskHandler != null) pendingOutput.Enqueue(e.Data); else console.WriteLine(e.Data); } };
        proc.BeginOutputReadLine();
        proc.BeginErrorReadLine();

        if (taskHandler == null)
        {
            await proc.WaitForExitAsync(Globals.ThisCancellationToken);
        }
        else
        {
            // Push the newest installer output line into the dialog about once a second. The
            // collapse prefix keeps the visible step log at ONE rolling entry (AddLog collapses
            // consecutive entries sharing the prefix) instead of hundreds of library-download lines.
            var progressPrefix = $"[{mod.Name} installer] ";
            var shownLine = "";
            var exitTask = proc.WaitForExitAsync(Globals.ThisCancellationToken);
            while (await Task.WhenAny(exitTask, Task.Delay(1000, Globals.ThisCancellationToken)) != exitTask)
            {
                var latest = shownLine;
                while (pendingOutput.TryDequeue(out var line)) { fullOutput.Add(line); latest = line; }
                if (latest != shownLine)
                {
                    shownLine = latest;
                    await taskHandler.UpdateProgress(log: progressPrefix + latest, collapseKey: progressPrefix);
                }
            }
            await exitTask;
        }

        proc.WaitForExit(); // drains the async output streams
        while (pendingOutput.TryDequeue(out var extraLine)) { fullOutput.Add(extraLine); }
        if (taskHandler != null && fullOutput.Count > 0)
        {
            // Full transcript as ONE debug entry - admins keep every line for diagnosis
            // (dumped before the exit-code check so a failed install is still diagnosable).
            await taskHandler.UpdateProgress(debugLog: $"{mod.Name} installer output:\n" + string.Join("\n", fullOutput));
        }
        if (proc.ExitCode != 0)
        {
            throw new Exception($"The {mod.Name} installer exited with code {proc.ExitCode}.");
        }
    }

    if (taskHandler != null)
    {
        await taskHandler.UpdateProgress(log: $"{mod.Name} installer finished. Wiring the launch command line...");
    }

    var vendor = loader == "Forge" ? "minecraftforge" : "neoforged";
    var argsName = isWindows ? "win_args.txt" : "unix_args.txt";
    var libraries = Path.Combine(root, "libraries");
    var argsFile = Directory.Exists(libraries)
        ? Directory.GetFiles(libraries, argsName, SearchOption.AllDirectories)
            .Where(f => f.Replace('\\', '/').Contains($"/net/{vendor}/"))
            .OrderByDescending(File.GetLastWriteTimeUtc)
            .FirstOrDefault()
        : null;
    if (argsFile == null)
    {
        throw new Exception($"The installer finished but {argsName} was not found under libraries/net/{vendor}.");
    }

    var relArgs = Path.GetRelativePath(root, argsFile).Replace('\\', '/');
    // Deliberately NOT @user_jvm_args.txt: JVM flags come from the panel's ${Xmx}/${Xms}
    // variables, and the game's Java auto-detection script keys off the FIRST @argfile in the
    // command line to find the loader's own jars - user_jvm_args.txt (service root) would send
    // it scanning root, where Java-8 bootstrap jars (staged installers) would mislead it.
    // Base the override on the blueprint default template so any admin JVM tuning is kept.
    lineOverridesDefault = true;
    lineTemplate = !string.IsNullOrEmpty(defaultTemplate) && defaultTemplate.Contains("-jar ${Jar}")
        ? defaultTemplate.Replace("-jar ${Jar}", "@" + relArgs)
        : "-Xmx${Xmx}M -Xms${Xms}M @" + relArgs + " nogui";
    console.WriteLine($"{mod.Name} launches through @{relArgs}.");
}
else
{
    // Runnable jar (Fabric server launcher, Velocity proxy): a non-override custom line whose
    // variable bag pins Jar at the staged file. The blueprint's default template evaluates with
    // the bag's Jar winning, so the service-level Jar variable (and the default line) stay vanilla.
    if (!File.Exists(Path.Combine(root, jar)))
    {
        console.WriteLine($"Warning: {jar} was not found in the service root.");
    }

    lineOverridesDefault = false;
    lineTemplate = string.IsNullOrEmpty(defaultTemplate) ? "-Xmx${Xmx}M -Xms${Xms}M -jar ${Jar} nogui" : defaultTemplate;
    lineVars["Jar"] = jar;

    service.Variables ??= new TCAdminVars();

    // Maps a Java major version onto the JRE tiers the auto-setup bundles under java/ - the
    // same grouping the game's "Detect java version" startup script uses.
    string JavaTier(int major)
    {
        if (major <= 8) return "java8";
        if (major <= 11) return "java11";
        if (major <= 16) return "java16";
        if (major == 17) return "java17";
        if (major <= 21) return "java21";
        return "java25";
    }

    // Rewrites the launch wrapper (minecraft_server.bat / .sh - it is just "<java> %*") to a
    // specific bundled JRE for an immediate effect; the startup script re-derives it on every
    // Automatic start (now honoring the JavaFor:<jar> memo written below).
    void WriteJavaLauncher(string tier)
    {
        if (string.IsNullOrEmpty(service.Executable)) return;
        var javaPath = Path.Combine(root, "java", tier, "bin", isWindows ? "java.exe" : "java");
        var javaCmd = File.Exists(javaPath) ? javaPath : "java";
        var contents = isWindows ? "\"" + javaCmd + "\" %*" : "#!/bin/bash\n\"" + javaCmd + "\" $*";
        File.WriteAllText(Path.Combine(root, service.Executable), contents);
        console.WriteLine($"Launch wrapper now uses {(javaCmd == "java" ? "the system java" : tier)}.");
    }

    if (loader == "Fabric")
    {
        // The Fabric server launcher bundle is a Java-8 bootstrap that downloads and boots the
        // real server in-process, so the game's class-file-based Java auto-detection reads it as
        // "needs Java 8" and modern Minecraft then crashes with UnsupportedClassVersionError.
        // The mod DOES know the Minecraft version it targets, so resolve the real requirement
        // from Mojang's version metadata and record it as a per-jar memo ("JavaFor:<jar>") the
        // detection script prefers over sniffing. Unlike the old global JavaVersion pin, the memo
        // only bites while THIS loader's command line is active - switching to another loader's
        // line (or back to vanilla) detects that line's own jar again.
        try
        {
            int javaMajor;
            using (var http = new HttpClient())
            {
                http.Timeout = TimeSpan.FromSeconds(30);
                var manifestJson = await http.GetStringAsync("https://launchermeta.mojang.com/mc/game/version_manifest_v2.json");
                string versionUrl = null;
                using (var manifest = JsonDocument.Parse(manifestJson))
                {
                    foreach (var v in manifest.RootElement.GetProperty("versions").EnumerateArray())
                    {
                        if (v.GetProperty("id").GetString() == mod.Version)
                        {
                            versionUrl = v.GetProperty("url").GetString();
                            break;
                        }
                    }
                }
                if (versionUrl == null)
                {
                    throw new Exception($"Minecraft version '{mod.Version}' not found in Mojang's version manifest.");
                }
                var verJson = await http.GetStringAsync(versionUrl);
                using (var ver = JsonDocument.Parse(verJson))
                {
                    javaMajor = ver.RootElement.GetProperty("javaVersion").GetProperty("majorVersion").GetInt32();
                }
            }

            var tier = JavaTier(javaMajor);
            service.Variables["JavaFor:" + jar] = "Java " + tier.Substring(4);

            // Old-scheme migration: earlier installs pinned the global JavaVersion and memoed the
            // prior selection. The per-jar memo supersedes the pin - restore the old selection,
            // but only while the pin is still active (a user who already went back to Automatic
            // keeps it; the stale memo is dropped either way).
            var beforeFabric = service.Variables.Parse<string>("JavaVersionBeforeFabric");
            if (!string.IsNullOrEmpty(beforeFabric))
            {
                var currentJavaSel = service.Variables.Parse<string>("JavaVersion");
                if (!string.IsNullOrEmpty(currentJavaSel) && currentJavaSel != "Automatic")
                {
                    service.Variables["JavaVersion"] = beforeFabric;
                    console.WriteLine($"Restored the Java selection to '{beforeFabric}' (the per-jar memo replaces the old pin).");
                }
                service.Variables.Remove("JavaVersionBeforeFabric");
            }

            WriteJavaLauncher(tier);
            console.WriteLine($"Minecraft {mod.Version} needs Java {javaMajor} - recorded it for {jar}.");
        }
        catch (Exception ex)
        {
            console.WriteLine($"Warning: could not resolve the Java requirement for Minecraft {mod.Version} ({ex.Message}). Automatic detection may pick Java 8 for the Fabric launcher - select the Java version manually if the server fails to start.");
        }
    }

    if (loader == "Velocity")
    {
        // Velocity generates velocity.toml on first boot with bind port 25577. Seed the config
        // with the service's game port so the proxy listens where the panel queries.
        var toml = Path.Combine(root, "velocity.toml");
        var gamePort = service.Ports != null ? service.Ports["GamePort"] : 0;
        if (!File.Exists(toml) && gamePort > 0)
        {
            File.WriteAllText(toml, "bind = \"0.0.0.0:" + gamePort + "\"\n");
            console.WriteLine($"Created velocity.toml binding the proxy to port {gamePort}.");
        }
        else if (File.Exists(toml))
        {
            console.WriteLine($"velocity.toml already exists - make sure its bind port matches the game port ({gamePort}).");
        }
    }
}

// ---- Converged: create or update THIS VERSION's custom command line, then make it active ----
// One line per installed mod row (per loader VERSION): the staged jars are versioned
// (fabric-26.2.jar), so several versions of a loader can coexist, each with its own line.
service.Variables ??= new TCAdminVars();
var cmdKey = "ModCmd:" + mod.ModId;                        // per-version (per mod row) tracking
var legacyCmdKey = "Mod:" + loader + ":CmdLineId";         // one-per-loader key from the first scheme
var bareJar = jar.Replace($"-{mod.Version}.jar", ".jar");  // pre-versioning shared filename

var serviceLines = db.ServiceCustomCommandLines.Where(x => x.ServiceId == service.ServiceId).ToList();
ServiceCustomCommandLine cmdRow = null;
var prevCmdId = service.Variables.Parse<long?>(cmdKey);
if (prevCmdId.HasValue) cmdRow = serviceLines.FirstOrDefault(x => x.CmdLineId == prevCmdId.Value);
// Legacy one-per-loader tracking: adopt only when the line really is this version's (same name)
// - a sibling version's line must not be stolen.
var legacyCmdId = service.Variables.Parse<long?>(legacyCmdKey);
if (cmdRow == null && legacyCmdId.HasValue)
    cmdRow = serviceLines.FirstOrDefault(x => x.CmdLineId == legacyCmdId.Value && x.Name == mod.Name);
// Exact-name fallback: an orphaned line (lost tracking variable) is reused instead of duplicated.
cmdRow ??= serviceLines.FirstOrDefault(x => x.Name == mod.Name);
if (cmdRow == null)
{
    cmdRow = new ServiceCustomCommandLine { ServiceId = service.ServiceId };
    db.ServiceCustomCommandLines.Add(cmdRow);
    serviceLines.Add(cmdRow);
}
cmdRow.Name = mod.Name;
cmdRow.CommandLine = lineTemplate;
cmdRow.OverrideDefault = lineOverridesDefault;
cmdRow.Variables = lineVars;
await db.SaveChangesAsync();

service.Variables[cmdKey] = cmdRow.CmdLineId;
if (legacyCmdId.HasValue && legacyCmdId.Value == cmdRow.CmdLineId) service.Variables.Remove(legacyCmdKey);

// Old-scheme migration 1: installs before the custom-line scheme pointed the DEFAULT line at
// the loader by mutating the service-level Jar variable. The custom line supersedes that - put
// the default line back to the blueprint default so "vanilla" stays selectable.
var legacyJar = service.Variables.Parse<string>("Jar");
if (!string.IsNullOrEmpty(legacyJar) && (legacyJar == jar || legacyJar == bareJar))
{
    service.Variables.Remove("Jar");
    console.WriteLine("Removed the legacy Jar variable override - the default command line is vanilla again.");
}

// Old-scheme migration 2: before jars were versioned the loader staged one shared bare jar
// (e.g. fabric.jar). Once no remaining line references it, drop its file and Java memo.
if (bareJar != jar && !serviceLines.Any(l => l.Variables != null && l.Variables.Values.Any(v => (v?.ToString() ?? "") == bareJar)))
{
    service.Variables.Remove("JavaFor:" + bareJar);
    var barePath = Path.Combine(root, bareJar);
    if (File.Exists(barePath))
    {
        try { File.Delete(barePath); console.WriteLine($"Deleted the legacy {bareJar}."); }
        catch (Exception ex) { console.WriteLine($"Warning: could not delete the legacy {bareJar} ({ex.Message})."); }
    }
}

// Service.Variables is a JSON column with no value comparer - in-place edits are invisible
// to change detection, so force the update.
db.Entry(service).State = EntityState.Modified;
await db.SaveChangesAsync();

var applied = await Globals.ServiceManager.ApplyCustomCommandLine(null, service.ServiceId, cmdRow.CmdLineId, false);
if (!applied)
{
    throw new Exception($"Could not apply custom command line {cmdRow.CmdLineId} ('{cmdRow.Name}').");
}

console.WriteLine($"{mod.Name} installed. The '{cmdRow.Name}' custom command line is now active - switch between installed loaders (or back to the default) from the Command Lines page.");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.Database.Entities;
using TCAdmin.SDK.Database.Managers;
using TCAdmin.Web.Shared.Models;
var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// MCJARFILES-MOD-UNINSTALL  <- marker referenced by the "Sync Minecraft Updates & Mods
// (mcjarfiles.com)" script, which finds this script by searching the game's scripts for this
// text and attaches it to every imported mod. Script ids differ between installs, so mods
// reference this script by marker, never by id. Keep the marker intact.
//
// Runs on BeforeModUninstall and reverses what the companion install script did for THIS
// VERSION of the loader (staged jars are versioned - fabric-26.2.jar - so several versions can
// be installed side by side, each with its own custom command line):
//   - Deletes this version's custom command line (found via the ModCmd:<modId> tracking
//     variable, the legacy Mod:<loader>:CmdLineId key, or an exact-name fallback so an orphaned
//     line still gets cleaned up) and its bookkeeping variables, including the JavaFor:<jar>
//     Java memo. If the deleted line was the active selection, the first predefined command
//     line is applied - or the blueprint default template is restored when the game has none.
//   - Forge / NeoForge: version-scoped library cleanup - each deleted line's @argfile names its
//     own version folder, and every libraries/net/<vendor>/*/<versionDir> is removed so sibling
//     versions keep their files. The whole vendor tree (plus the legacy UnparsedCommandline
//     override) is only swept when NO line of this loader remains.
//   - Legacy state from the pre-custom-command-line scheme is still reverted: the service-level
//     Jar variable override, the legacy override template and the JavaVersionBeforeFabric memo.
//     Leftover bare-named jars (fabric.jar) are removed once nothing references them.
// The staged jar itself is tracked by the mod install and removed by the normal uninstall flow.

var console = Globals.ScriptConsole;
var mod = Globals.GetValue<BlueprintMod>(nameof(BlueprintMod));
var service = Globals.ThisService;
if (mod == null || service == null)
{
    console.WriteLine("No mod or service in scope - nothing to do.");
    return;
}

var db = Globals.ServiceManager.TCAdminDbContext;
var root = service.RootDirectory;

// The sync imports one row per version ("Forge 1.21.8"), so the loader is the name's first
// token - bare legacy names ("Forge") dispatch the same way.
var loader = mod.Name.Split(' ')[0];

// ---- Custom command line cleanup ----
service.Variables ??= new TCAdminVars();
var cmdKey = "ModCmd:" + mod.ModId;
var legacyCmdKey = "Mod:" + loader + ":CmdLineId";
var jar = mod.SaveAsFilename;
var bareJar = string.IsNullOrEmpty(jar) ? null : jar.Replace($"-{mod.Version}.jar", ".jar");

var serviceLines = db.ServiceCustomCommandLines.Where(x => x.ServiceId == service.ServiceId).ToList();
var trackedCmdId = service.Variables.Parse<long?>(cmdKey);
var legacyCmdId = service.Variables.Parse<long?>(legacyCmdKey);
var cmdRows = serviceLines
    .Where(x => (trackedCmdId.HasValue && x.CmdLineId == trackedCmdId.Value) || x.Name == mod.Name)
    .ToList();

var selectedWasThisMod = false;
if (cmdRows.Count > 0)
{
    var selected = service.Variables.Parse<string>("__SelectedCmdLine");
    selectedWasThisMod = cmdRows.Any(r => selected == "CUS:" + r.CmdLineId);

    db.ServiceCustomCommandLines.RemoveRange(cmdRows);
    await db.SaveChangesAsync();
    serviceLines = serviceLines.Except(cmdRows).ToList();
    console.WriteLine($"Deleted the '{string.Join("', '", cmdRows.Select(r => r.Name))}' custom command line{(cmdRows.Count > 1 ? "s" : "")}.");
}

var varsChanged = false;
if (service.Variables.Remove(cmdKey)) varsChanged = true;
if (legacyCmdId.HasValue && cmdRows.Any(r => r.CmdLineId == legacyCmdId.Value) && service.Variables.Remove(legacyCmdKey)) varsChanged = true;
if (!string.IsNullOrEmpty(jar) && service.Variables.Remove("JavaFor:" + jar)) varsChanged = true;
// The pre-versioning bare jar's memo goes too, once no remaining line references that jar.
var bareStillReferenced = bareJar != null && bareJar != jar
    && serviceLines.Any(l => l.Variables != null && l.Variables.Values.Any(v => (v?.ToString() ?? "") == bareJar));
if (bareJar != null && bareJar != jar && !bareStillReferenced && service.Variables.Remove("JavaFor:" + bareJar)) varsChanged = true;
if (selectedWasThisMod && service.Variables.Remove("__SelectedCmdLine")) varsChanged = true;
if (varsChanged)
{
    // Service.Variables is a JSON column with no value comparer - force the update.
    db.Entry(service).State = EntityState.Modified;
    await db.SaveChangesAsync();
}

if (selectedWasThisMod)
{
    // The active selection just got deleted - fall back to the first predefined command line
    // (the blueprint default template when the game defines none).
    var predef = service.Blueprint?.CommandlineConfig?.PredefinedCommandlines?.FirstOrDefault();
    if (predef != null)
    {
        await Globals.ServiceManager.ApplyPredefinedCommandLine(null, service.ServiceId, predef.Id, false);
        console.WriteLine($"Applied the '{predef.Name}' predefined command line.");
    }
    else
    {
        service.OverrideCommandline = false;
        service.UnparsedCommandline = null;
        await Globals.ServiceManager.RefreshActiveCommandLine(null, service, new CommandlineRefreshOptions { ThrowOnError = true });
        await db.SaveChangesAsync();
        console.WriteLine("No predefined command lines - restored the blueprint default command line.");
    }
}

// ---- Legacy revert + installer artifact cleanup ----
if (loader == "Forge" || loader == "NeoForge")
{
    var vendor = loader == "Forge" ? "minecraftforge" : "neoforged";
    var vendorRoot = Path.Combine(root, "libraries", "net", vendor);

    // Version-scoped cleanup: the deleted line's @argfile names this version's folder
    // (libraries/net/<vendor>/<loaderdir>/<versionDir>/<os>_args.txt). The installer stamps the
    // SAME version folder under every sibling artifact dir (forge, fmlcore, fmlloader, ...), so
    // remove <versionDir> under each of them - sibling VERSIONS keep their own folders.
    var versionDirNames = new List<string>();
    foreach (var rowLine in cmdRows)
    {
        var argSeg = (rowLine.CommandLine ?? "").Split(' ').FirstOrDefault(s => s.StartsWith("@") && s.EndsWith(".txt"));
        if (argSeg == null) continue;
        var argRel = argSeg.Substring(1).Replace('/', Path.DirectorySeparatorChar);
        var versionDir = Path.GetDirectoryName(Path.Combine(root, argRel));
        if (versionDir == null || !versionDir.Replace('\\', '/').Contains($"/net/{vendor}/")) continue;
        var versionDirName = Path.GetFileName(versionDir);
        if (!string.IsNullOrEmpty(versionDirName)) versionDirNames.Add(versionDirName);
    }
    foreach (var versionDirName in versionDirNames.Distinct())
    {
        if (!Directory.Exists(vendorRoot)) break;
        foreach (var artifactDir in Directory.GetDirectories(vendorRoot))
        {
            var target = Path.Combine(artifactDir, versionDirName);
            if (Directory.Exists(target))
            {
                Directory.Delete(target, true);
                console.WriteLine($"Deleted libraries/net/{vendor}/{Path.GetFileName(artifactDir)}/{versionDirName}.");
            }
        }
        // The installer's root leftovers are versioned the same way (forge-<versionDir>-shim.jar).
        foreach (var stray in Directory.GetFiles(root, $"{loader.ToLower()}-{versionDirName}*.jar"))
        {
            File.Delete(stray);
            console.WriteLine($"Deleted {Path.GetFileName(stray)}.");
        }
    }

    // Only when NO line of this loader remains: sweep the whole vendor tree (covers legacy
    // installs that never had a custom line) and revert the legacy override template.
    var loaderStillPresent = serviceLines.Any(l => (l.CommandLine ?? "").Contains($"/net/{vendor}/"));
    if (!loaderStillPresent)
    {
        if (service.OverrideCommandline && (service.UnparsedCommandline ?? "").Contains(vendor))
        {
            // Override off + NULL template = the refresh re-adopts the blueprint template.
            service.OverrideCommandline = false;
            service.UnparsedCommandline = null;
            await Globals.ServiceManager.RefreshActiveCommandLine(null, service, new CommandlineRefreshOptions { ThrowOnError = true });
            await db.SaveChangesAsync();
            console.WriteLine("Restored the blueprint command line (legacy override).");
        }

        if (Directory.Exists(vendorRoot))
        {
            Directory.Delete(vendorRoot, true);
            console.WriteLine($"Deleted libraries/net/{vendor}.");
        }

        // Broad root sweep, legacy-safe now that no version of this loader remains. Any stray
        // bootstrap jar in root can mislead the game's Java auto-detection.
        foreach (var stray in Directory.GetFiles(root, $"{loader.ToLower()}-*.jar"))
        {
            File.Delete(stray);
            console.WriteLine($"Deleted {Path.GetFileName(stray)}.");
        }
    }

    // Latest-install-wins artifacts, unused by the custom lines - always safe to drop.
    foreach (var file in new[] { "run.bat", "run.sh", "user_jvm_args.txt", string.IsNullOrEmpty(jar) ? null : jar + ".log" })
    {
        if (file == null) continue;
        var path = Path.Combine(root, file);
        if (File.Exists(path))
        {
            File.Delete(path);
            console.WriteLine($"Deleted {file}.");
        }
    }
}
else
{
    // Legacy scheme only: older installs pointed the service-level Jar variable at the staged
    // jar. Current installs pin Jar inside the custom line's variable bag instead, so the guard
    // below only fires for services that never reinstalled under the new scheme.
    // Values loaded from the JSON column come back as JsonElement - Parse<string> normalizes.
    var currentJar = service.Variables?.Parse<string>("Jar");
    if (!string.IsNullOrEmpty(currentJar) && (currentJar == jar || (bareJar != null && currentJar == bareJar)))
    {
        service.Variables.Remove("Jar");

        if (loader == "Fabric")
        {
            // The legacy install pinned JavaVersion (the class-file auto-detection misreads the
            // Fabric launcher bootstrap as Java 8) - restore whatever selection was active
            // before. "Automatic" makes the startup script re-detect and rewrite the launch
            // wrapper on the next start, so the stale pin in the wrapper file heals itself.
            var previous = service.Variables.Parse<string>("JavaVersionBeforeFabric");
            if (!string.IsNullOrEmpty(previous))
            {
                service.Variables["JavaVersion"] = previous;
                service.Variables.Remove("JavaVersionBeforeFabric");
                console.WriteLine($"Restored the Java selection to '{previous}'.");
            }
        }

        // Service.Variables is a JSON column with no value comparer - force the update.
        db.Entry(service).State = EntityState.Modified;
        await Globals.ServiceManager.RefreshActiveCommandLine(null, service, new CommandlineRefreshOptions { ThrowOnError = true });
        await db.SaveChangesAsync();
        console.WriteLine("Removed the legacy Jar variable override; the blueprint default launches again.");
    }
}

// Defense-in-depth: the staged jar is normally tracked by the install's FileSystemWatcher and
// removed by the uninstall flow, but a reinstall over an EXISTING file fires no Created event
// (nothing gets tracked), so the flow can leave it behind - and any stray bootstrap jar in the
// root misleads the game's Java auto-detection. Best-effort: a locked file only warns. The
// pre-versioning bare jar (fabric.jar) is included once nothing references it.
var stagedNames = new List<string>();
if (!string.IsNullOrEmpty(jar)) stagedNames.Add(jar);
if (bareJar != null && bareJar != jar && !bareStillReferenced) stagedNames.Add(bareJar);
foreach (var stagedName in stagedNames)
{
    var staged = Path.Combine(root, stagedName);
    if (File.Exists(staged))
    {
        try
        {
            File.Delete(staged);
            console.WriteLine($"Deleted {stagedName}.");
        }
        catch (Exception ex)
        {
            console.WriteLine($"Warning: could not delete {stagedName} ({ex.Message}) - delete it manually.");
        }
    }
}

if (loader == "Fabric")
{
    // The Fabric launcher caches the downloaded server + loader under .fabric at first boot.
    // The cache is shared by every Fabric version, so only drop it when no Fabric line remains
    // (it regenerates on next boot either way).
    var fabricCache = Path.Combine(root, ".fabric");
    var fabricStillPresent = serviceLines.Any(l => l.Name == "Fabric" || l.Name.StartsWith("Fabric "));
    if (Directory.Exists(fabricCache) && !fabricStillPresent)
    {
        try
        {
            Directory.Delete(fabricCache, true);
            console.WriteLine("Deleted the .fabric cache.");
        }
        catch (Exception ex)
        {
            console.WriteLine($"Warning: could not delete .fabric ({ex.Message}).");
        }
    }
}
